{
  "name": "Busy sites",
  "scope": "site",
  "kind": "threshold",
  "expr": "pressfleet_site_php_fpm_active_processes / pressfleet_site_php_fpm_max_children",
  "operator": "gt",
  "threshold": 0.8,
  "for_seconds": 300,
  "severity": "warning",
  "annotations": {
    "summary": "{{ .Labels.site_id }}: {{ humanizePercentage .Value }} of PHP-FPM workers are busy"
  }
}
